OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager) {
    OPJ_UINT32 current_tile = 0;
    OPJ_UINT32 num_tiles = p_j2k->cinfo->numresolution;
    OPJ_UINT32 tile_index;
    OPJ_UINT32 tile_part = 0;
    OPJ_UINT32 tile_parts_per_tile = p_j2k->cinfo->tile_info[0].num_tile_parts;
    OPJ_UINT32 tile_data_size;
    OPJ_UINT32 bytes_written = 0;

    for (tile_index = 0; tile_index < num_tiles; tile_index++) {
        if (p_j2k->cinfo->tile_info[tile_index].cinema_mode) {
            /* Handle cinema format specifics */
            if (!j2k_write_cinema_sot(p_j2k, tile_index, tile_part, p_stream, p_manager)) {
                return OPJ_FALSE;
            }
        } else {
            if (!j2k_write_sot(p_j2k, tile_index, tile_part, p_stream, p_manager)) {
                return OPJ_FALSE;
            }
        }

        tile_data_size = p_j2k->cinfo->tile_info[tile_index].tile_data_size;
        if (bytes_written + tile_data_size > p_total_data_size) {
            tile_data_size = p_total_data_size - bytes_written;
        }

        if (!opj_stream_write(p_stream, p_data + bytes_written, tile_data_size)) {
            return OPJ_FALSE;
        }

        bytes_written += tile_data_size;

        if (!j2k_write_sod(p_j2k, tile_index, tile_part, p_stream, p_manager)) {
            return OPJ_FALSE;
        }

        tile_part++;
    }

    *p_data_written = bytes_written;
    return OPJ_TRUE;
}

OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager) {
    OPJ_UINT32 tile_index = 0;
    OPJ_UINT32 tile_part_index = 0;
    OPJ_BOOL success = OPJ_TRUE;
    OPJ_UINT32 total_written = 0;
    OPJ_BYTE *current_data = p_data;

    for (tile_index = 0; tile_index < p_j2k->num_tiles && success; ++tile_index) {
        opj_tcp_t *tcp = p_j2k->tiles[tile_index].tcp;
        OPJ_UINT32 num_tile_parts = tcp->numpocs;

        for (tile_part_index = 0; tile_part_index < num_tile_parts && success; ++tile_part_index) {
            OPJ_UINT32 tile_part_size = 0;
            OPJ_BYTE *tile_part_data = NULL;

            /* Calculate or obtain size and data for the current tile part */
            tile_part_size = get_tile_part_data(p_j2k, tile_index, tile_part_index, &tile_part_data);

            if (tile_part_data == NULL || tile_part_size == 0) {
                success = OPJ_FALSE;
                continue;
            }

            if (total_written + tile_part_size > p_total_data_size) {
                success = OPJ_FALSE;
                continue;
            }

            /* Write SOT marker if necessary */
            if (write_sot_marker(p_stream, tile_index, tile_part_index, p_manager) != OPJ_TRUE) {
                success = OPJ_FALSE;
                continue;
            }

            /* Write SOD marker if necessary */
            if (write_sod_marker(p_stream, tile_index, tile_part_index, p_manager) != OPJ_TRUE) {
                success = OPJ_FALSE;
                continue;
            }

            /* Write tile part data to the stream */
            if (opj_stream_write(p_stream, tile_part_data, tile_part_size) != tile_part_size) {
                success = OPJ_FALSE;
                continue;
            }

            current_data = p_data + total_written;
            total_written += tile_part_size;
            *p_data_written = total_written;
        }
    }

    return success;
}

OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager) {
    OPJ_UINT32 tile_count = 0;
    OPJ_UINT32 tile_data_size = 0;
    OPJ_UINT32 tile_index = 0;
    OPJ_UINT32 tile_part_index = 0;
    OPJ_BOOL result = OPJ_TRUE;

    for (tile_index = 0; tile_index < p_j2k->num_tiles; ++tile_index) {
        for (tile_part_index = 0; tile_part_index < p_j2k->tile[tile_index].num_parts; ++tile_part_index) {
            /* Write Start Of Tile (SOT) marker */
            if (!opj_write_bytes(p_stream, p_data + *p_data_written, (const OPJ_BYTE *)"\xFF\x5F", 2, p_manager)) {
                result = OPJ_FALSE;
                goto cleanup;
            }
            *p_data_written += 2;

            /* Write tile part header data */
            tile_data_size = p_j2k->tile[tile_index].tile_part_data[tile_part_index].size;
            if (tile_data_size > (p_total_data_size - *p_data_written)) {
                result = OPJ_FALSE;
                goto cleanup;
            }

            if (!opj_stream_write_data(p_stream, p_data + *p_data_written,
                                       tile_data_size, p_manager)) {
                result = OPJ_FALSE;
                goto cleanup;
            }

            *p_data_written += tile_data_size;

            /* Write End Of Data (SOD) marker if not last part */
            if (tile_part_index < (p_j2k->tile[tile_index].num_parts - 1)) {
                if (!opj_write_bytes(p_stream, p_data + *p_data_written, (const OPJ_BYTE *)"\xFF\xDA", 2, p_manager)) {
                    result = OPJ_FALSE;
                    goto cleanup;
                }
                *p_data_written += 2;
            }

            /* Manage tile part number */
            ++tile_count;
        }
    }

cleanup:
    return result;
}

OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager) {
    OPJ_UINT32 tile_count = 0;
    OPJ_UINT32 tile_number = 0;
    OPJ_UINT32 current_data_size = 0;
    OPJ_BOOL success = OPJ_TRUE;

    while (tile_count < p_j2k->num_tiles && success) {
        OPJ_BYTE *tile_data = p_data + current_data_size;

        /* Write the Start Of Tile (SOT) marker */
        if (!opj_j2k_write_sot(p_j2k, tile_number, p_stream, p_manager)) {
            success = OPJ_FALSE;
            break;
        }

        /* Write the Start Of Data (SOD) marker */
        if (!opj_j2k_write_sod(p_j2k, p_stream, p_manager)) {
            success = OPJ_FALSE;
            break;
        }

        /* Copy the tile data into the buffer */
        OPJ_UINT32 tile_data_size = 0;
        if (!opj_j2k_get_tile_data_size(p_j2k, &tile_data_size, tile_number)) {
            success = OPJ_FALSE;
            break;
        }

        if (current_data_size + tile_data_size > p_total_data_size) {
            success = OPJ_FALSE;
            break;
        }

        memcpy(tile_data, p_j2k->tile_data[tile_number], tile_data_size);
        current_data_size += tile_data_size;
        *p_data_written = current_data_size;

        /* Handle cinema format specific logic if required */
        if (p_j2k->cinema_format) {
            if (!opj_j2k_handle_cinema_format(p_j2k, tile_number, p_stream, p_manager)) {
                success = OPJ_FALSE;
                break;
            }
        }

        tile_count++;
        tile_number++;
    }

    /* Write the End Of Data (EOD) marker if required */
    if (success && tile_count > 0) {
        if (!opj_j2k_write_eod(p_j2k, p_stream, p_manager)) {
            success = OPJ_FALSE;
        }
    }

    return success;
}

OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager) {
    OPJ_UINT32 tile_index = 0;
    OPJ_UINT32 tile_part_idx = 0;
    OPJ_BOOL success = OPJ_TRUE;

    while (tile_index < p_j2k->num_tiles) {
        for (tile_part_idx = 0; tile_part_idx < p_j2k->tile[tile_index].num_parts; ++tile_part_idx) {
            OPJ_UINT32 part_size = p_j2k->tile[tile_index].part_sizes[tile_part_idx];
            if (*p_data_written + part_size > p_total_data_size) {
                /* Not enough buffer space left */
                success = OPJ_FALSE;
                break;
            }

            /* Write SOT marker */
            if (!opj_write_bytes(p_stream, (OPJ_BYTE*)"SOT", 3, p_manager)) {
                success = OPJ_FALSE;
                break;
            }

            /* Write tile part data */
            if (!opj_stream_write_full(p_stream, p_data, part_size)) {
                success = OPJ_FALSE;
                break;
            }

            *p_data_written += part_size;

            /* Write SOD marker */
            if (!opj_write_bytes(p_stream, (OPJ_BYTE*)"SOD", 3, p_manager)) {
                success = OPJ_FALSE;
                break;
            }

            /* Update tile part number */
            p_j2k->tile[tile_index].current_part++;
        }

        if (!success) {
            break;
        }

        tile_index++;
    }

    return success;
}
